/**
 * 人生之书的纯 JS 引擎。
 *
 * 和 @ohos/dsh-sanguo 是同一条分工：引擎是裁判，模型只是叙述者。
 * 引擎只做三件事——把一章的选项结算成六个数值、把选择记进欲望账本、
 * 在第五章之后给出一个结局 id。它不生成任何叙述文本。
 */

export const STAT_KEYS = ['money', 'health', 'love', 'freedom', 'parents', 'regret']

export const STAT_LABELS = {
  money: '钱',
  health: '健康',
  love: '爱',
  freedom: '自由',
  parents: '父母',
  regret: '遗憾'
}

export const DESIRE_LABELS = {
  money: '钱',
  health: '健康',
  love: '被爱',
  freedom: '自由',
  parents: '被期待',
  self: '自己'
}

const START = { money: 50, health: 80, love: 50, freedom: 50, parents: 50, regret: 10 }

const clamp = (value, low, high) => Math.min(high, Math.max(low, Number.isFinite(value) ? value : low))

function hash(text) {
  let value = 2166136261 >>> 0
  for (let index = 0; index < text.length; index += 1) {
    value ^= text.charCodeAt(index)
    value = Math.imul(value, 16777619) >>> 0
  }
  return value
}

/** 新的一本书。名字只影响复现，不影响规则。 */
export function createSave(name) {
  const seedName = typeof name === 'string' && name.length > 0 ? name : 'xiaoshi'
  return {
    schema: 1,
    seed: hash(seedName),
    name: '小狮',
    age: 18,
    year: 2016,
    chapter: 0,
    stats: { ...START },
    tags: { city: '临江', school: '', job: '', partner: '' },
    desires: { money: 0, freedom: 0, love: 0, parents: 0, self: 0 },
    flags: {},
    log: [],
    finished: false,
    endingId: ''
  }
}

/** 当前章；越界时返回 null（已经走到结局）。 */
export function chapterOf(state, data) {
  if (state.finished === true) return null
  return data?.chapters?.[state.chapter] ?? null
}

/** 把一章投影成 UI 和模型都能读的形状。 */
export function sceneOf(state, data) {
  const chapter = chapterOf(state, data)
  if (chapter === null) {
    return { finished: true, ending: endingFor(state, data), stats: state.stats, tags: state.tags }
  }
  return {
    finished: false,
    when: `${chapter.year}年`,
    age: chapter.age,
    year: chapter.year,
    chapter: state.chapter,
    total: data.chapters.length,
    id: chapter.id,
    title: chapter.title,
    narration: chapter.narration,
    options: (chapter.options ?? []).map((option) => ({
      id: option.id,
      label: option.label,
      desire: option.desire,
      desireLabel: DESIRE_LABELS[option.desire] ?? option.desire,
      canon: option.canon === true,
      effects: option.effects ?? {},
      tags: option.tags ?? {},
      note: option.note ?? ''
    })),
    stats: { ...state.stats },
    tags: { ...state.tags },
    desires: { ...state.desires }
  }
}

/** 选一个选项：结算数值、记欲望、翻页。 */
export function choose(state, data, optionId) {
  const chapter = chapterOf(state, data)
  if (chapter === null) {
    throw new Error('这一页已经翻完了')
  }
  const option = (chapter.options ?? []).find((item) => item.id === optionId)
  if (option === undefined) {
    throw new Error(`「${chapter.title}」没有这个选项：${optionId}`)
  }

  const stats = { ...state.stats }
  for (const [key, raw] of Object.entries(option.effects ?? {})) {
    if (!STAT_KEYS.includes(key)) continue
    const value = Number(raw)
    if (!Number.isFinite(value)) continue
    stats[key] = clamp((stats[key] ?? 0) + value, 0, 100)
  }

  const tags = { ...state.tags, ...(option.tags ?? {}) }
  const desires = { ...state.desires }
  if (option.desire !== undefined) {
    desires[option.desire] = (desires[option.desire] ?? 0) + 1
  }

  const nextChapter = state.chapter + 1
  const nextChapterData = data.chapters?.[nextChapter]
  const finished = nextChapterData === undefined
  const next = {
    ...state,
    stats,
    tags,
    desires,
    chapter: nextChapter,
    year: nextChapterData?.year ?? chapter.year,
    age: nextChapterData?.age ?? chapter.age,
    finished,
    endingId: finished ? endingFor({ ...state, stats, tags, desires }, data).id : '',
    log: [
      ...(Array.isArray(state.log) ? state.log : []),
      {
        chapter: chapter.id,
        age: chapter.age,
        title: chapter.title,
        option: option.id,
        label: option.label,
        desire: option.desire,
        effects: option.effects ?? {}
      }
    ]
  }

  return { state: next, option, effects: option.effects ?? {}, next: sceneOf(next, data) }
}

/**
 * 结局：先看“自己”，再看野心 / 自由 / 爱 / 回家，最后落回标准答案。
 * 每个结局都可达；没有“没有结局”的状态。
 */
export function endingFor(state, data) {
  const stats = state?.stats ?? START
  const endings = data?.endings ?? []
  const pick = (id) => endings.find((ending) => ending.id === id) ?? endings[0] ?? {
    id: 'standard', title: '标准答案', subtitle: '', text: '', comment: '', hint: ''
  }

  if (stats.regret <= 20 && stats.health >= 55 && stats.freedom >= 55) return pick('self')
  if (stats.money >= 80 && stats.health < 50) return pick('ambition')
  if (stats.freedom >= 70) return pick('freedom')
  if (stats.love >= 70) return pick('love')
  if (stats.parents >= 70) return pick('home')
  return pick('standard')
}

/** 给模型的紧凑 digest；不含任何叙述文本以外的世界数据。 */
export function buildDigest(state, data) {
  const chapter = chapterOf(state, data)
  const canon = data?.canon ?? {}
  const base = {
    title: data?.title ?? '小狮日记 · 人生之书',
    when: chapter === null ? `${state.year}年` : `${chapter.year}年`,
    age: chapter?.age ?? state.age,
    chapter: state.chapter,
    total: data?.chapters?.length ?? 0,
    stats: { ...state.stats },
    tags: { ...state.tags },
    desires: { ...state.desires },
    people: (canon.people ?? []).map((person) => ({ name: person.name, role: person.role }))
  }
  if (chapter === null) {
    return { ...base, finished: true, ending: endingFor(state, data) }
  }
  return {
    ...base,
    finished: false,
    chapterId: chapter.id,
    sceneTitle: chapter.title,
    narration: chapter.narration,
    options: (chapter.options ?? []).map((option) => ({
      id: option.id,
      label: option.label,
      desire: DESIRE_LABELS[option.desire] ?? option.desire,
      canon: option.canon === true,
      effects: option.effects ?? {},
      note: option.note ?? ''
    }))
  }
}

/** 给模型的人类可读摘要。 */
export function renderDigest(digest) {
  const lines = [
    `${digest.when} · ${digest.age}岁 · ${digest.title}`,
    `钱 ${digest.stats.money}　健康 ${digest.stats.health}　爱 ${digest.stats.love}　` +
      `自由 ${digest.stats.freedom}　父母 ${digest.stats.parents}　遗憾 ${digest.stats.regret}`,
    `城市 ${digest.tags.city}　学校 ${digest.tags.school || '—'}　工作 ${digest.tags.job || '—'}　` +
      `伴侣 ${digest.tags.partner || '—'}`,
    `欲望账本：${Object.entries(digest.desires).filter(([, count]) => count > 0).map(([key, count]) => `${DESIRE_LABELS[key] ?? key}×${count}`).join('、') || '无'}`
  ]
  if (digest.finished === true) {
    lines.push(`结局：${digest.ending.title}——${digest.ending.subtitle}`)
    return lines.join('\n')
  }
  lines.push('', `【${digest.sceneTitle}】`, digest.narration)
  for (const option of digest.options ?? []) {
    lines.push(
      `- ${option.label}（${option.desire}${option.canon ? ' · 当年' : ' · 如果'}）` +
      `${option.note.length > 0 ? `：${option.note}` : ''}`
    )
  }
  return lines.join('\n')
}

/** 写进 `.life/life.json` 的投影；卡面只读它。 */
export function projection(state, data) {
  const scene = sceneOf(state, data)
  return {
    schema: 1,
    present: true,
    when: scene.when,
    age: scene.age,
    chapter: state.chapter,
    total: data?.chapters?.length ?? 0,
    title: scene.finished ? '人生之书' : scene.title,
    narration: scene.finished ? '' : scene.narration,
    stats: state.stats,
    tags: state.tags,
    desires: state.desires,
    finished: state.finished,
    ending: scene.finished ? scene.ending : null,
    options: scene.finished ? [] : scene.options,
    generatedAt: new Date().toISOString()
  }
}
